const upsertRongCloudArtifact = `-- name: UpsertRongCloudArtifact :one
INSERT INTO rongcloud_artifact (
    artifact_id, discussion_id, artifact_type, title, content, version, base_version
) VALUES (
    $1, $2, $3, $4, $5, $6, $7
)
ON CONFLICT (discussion_id, artifact_type) DO UPDATE SET
    title        = EXCLUDED.title,
    content      = EXCLUDED.content,
    version      = EXCLUDED.version,
    base_version = EXCLUDED.base_version,
    updated_at   = now()
RETURNING artifact_id, discussion_id, artifact_type, title, content, version, base_version, created_at, updated_at
`

type UpsertRongCloudArtifactParams struct {
	ArtifactID   string `json:"artifact_id"`
	DiscussionID string `json:"discussion_id"`
	ArtifactType string `json:"artifact_type"`
	Title        string `json:"title"`
	Content      string `json:"content"`
	Version      int32  `json:"version"`
	BaseVersion  int32  `json:"base_version"`
}

// 一个讨论每种 artifact_type 只有一行（UNIQUE(discussion_id, artifact_type)）。合成
// 结果可能被多次更新，version 递增、base_version 记录它基于哪一版。
func (q *Queries) UpsertRongCloudArtifact(ctx context.Context, arg UpsertRongCloudArtifactParams) (RongcloudArtifact, error) {
	row := q.db.QueryRow(ctx, upsertRongCloudArtifact,
		arg.ArtifactID,
		arg.DiscussionID,
		arg.ArtifactType,
		arg.Title,
		arg.Content,
		arg.Version,
		arg.BaseVersion,
	)
	var i RongcloudArtifact
	err := row.Scan(
		&i.ArtifactID,
		&i.DiscussionID,
		&i.ArtifactType,
		&i.Title,
		&i.Content,
		&i.Version,
		&i.BaseVersion,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
